mapper.select:
select *
  from (
    select 
      from market_overview_snapshots
     where deleted_at is null
       and trade_date >= #{startDate}
     order by trade_date desc
     limit #{limit}
  ) t
 order by trade_date asc

select trade_date
  from (
    select distinct trade_date
      from market_pulse_sector_daily_snapshots
     where deleted_at is null
     order by trade_date desc
     limit #{limit}
  ) t
 order by trade_date asc

select from market_pulse_sector_daily_snapshots where deleted_at is null and trade_date in
#{tradeDate}
order by trade_date asc, rank_by_change asc nulls last, change_pct desc nulls last, sector_name asc

select 
  from mkt_index_return_daily
 where deleted_at is null
   and window_days = #{windowDays}
   and trade_date between #{startDate} and #{endDate}
 order by trade_date asc, index_code asc
